```java
import java.io.*;
import java.util.*;

public class CommandExecutor {
    public void executeSystemCommand(String filename) {
        try {
            // FIXED: Use ProcessBuilder with a List of arguments.
            // This treats the user input strictly as an argument rather than part of the command string,
            // preventing shell metacharacters (like ';', '&', or '|') from being interpreted.
            List<String> command = new ArrayList<>();
            command.add("ls");
            command.add("-l");
            command.add(filename);

            ProcessBuilder processBuilder = new ProcessBuilder(command);
            Process process = processBuilder.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

